/* Generated by "dfw tokens build" from design/tokens/*.json (W3C DTCG). Do not edit by hand. */
:root {
  --color-blue-600: #0055dd;
  --color-ink: #1c1b1a;
  --color-accent: var(--color-blue-600);
  --color-veil: rgb(15.3 17.85 22.95 / 0.4);
  --color-soft: oklch(0.9 0.05 250);
  --color-brand: rgb(255 102 0 / 0.5);
  --color-mix: #336699;
  --space-2: 8px;
  --space-4: calc(var(--space-2) * 2);
  --space-gutter: var(--space-4);
  --radius-md: 8px;
  --border-width: 1px;
  --size-control: 40px;
  --font-family-body: "Source Sans 3", sans-serif;
  --font-size-md: 17px;
  --font-size-lg: 1.25rem;
  --font-weight-regular: 400;
  --font-weight-bold: 700;
  --font-leading-body: 1.5;
  --font-tracking-tight: -0.02em;
  --font-eyebrow-case: uppercase;
  --font-eyebrow-note: free text;
  --type-body-font-family: var(--font-family-body);
  --type-body-font-size: var(--font-size-md);
  --type-body-font-weight: var(--font-weight-regular);
  --type-body-letter-spacing: 0px;
  --type-body-line-height: var(--font-leading-body);
  --shadow-sm: 0px 1px 2px 0px rgb(15.3 17.85 22.95 / 0.06);
  --shadow-inner: inset 0px 1px 0px 0px var(--color-ink);
  --duration-fast: 150ms;
  --easing-out: cubic-bezier(0.2, 0, 0, 1);
  --opacity-muted: 0.45;
}

[data-theme="dark"] {
  --color-ink: #eeeeee;
  --color-accent: var(--color-blue-600);
  --shadow-sm: 0px 2px 4px 0px rgb(0 0 0 / 0.5);
}

